def main(argv):
    if sys.implementation.name != "cpython" or sys.version_info[:2] != (3, 12):
        print(
            "refusing: need CPython 3.12, found %s %s"
            % (sys.implementation.name, sys.version.split()[0]),
            file=sys.stderr,
        )
        return 2
    print("interpreter: " + sys.version, file=sys.stderr)
    cases = []
    for text in INPUTS:
        try:
            json.loads(text)
            cls, msg = "ok", ""
        except json.JSONDecodeError as e:
            cls, msg = "JSONDecodeError", str(e)
        except ValueError as e:
            cls, msg = "ValueError", str(e)
        cases.append({"input": text, "repr": repr(text), "class": cls, "message": msg})
    doc = {"python_version": sys.version, "cases": cases}
    default = os.path.join(
        os.path.dirname(os.path.abspath(__file__)), "cpython312_json_parity.json"
    )
    out = argv[1] if len(argv) > 1 else default
    with open(out, "w", encoding="utf-8") as f:
        f.write(json.dumps(doc, indent=2) + "\n")
    print("wrote %d cases to %s" % (len(cases), out), file=sys.stderr)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
